package com.grievancecampus.dao;
import java.sql.*;import java.util.*;import com.dao.DBConnection;import com.grievancecampus.model.User;
public class DashboardDAO {
 public Map<String,Long> counts(User u)throws SQLException{Map<String,Long> m=new LinkedHashMap<>();String role=u.getRole();
  if("STUDENT".equals(role)){m.put("total",count("SELECT COUNT(*) FROM gc_grievances WHERE student_id=? AND deleted_at IS NULL",u.getId()));for(String s:new String[]{"PENDING","RESOLVED","REJECTED"})m.put(s.toLowerCase(),count("SELECT COUNT(*) FROM gc_grievances WHERE student_id=? AND status=? AND deleted_at IS NULL",u.getId(),s));}
  else if("STAFF".equals(role)){for(String s:new String[]{"total","pending","completed"})m.put(s,count("SELECT COUNT(*) FROM gc_assignments a JOIN gc_grievances g ON g.grievance_id=a.grievance_id WHERE a.assignee_id=? AND g.deleted_at IS NULL"+("total".equals(s)?"":" AND a.status=?"),u.getId(),"total".equals(s)?null:s.toUpperCase()));}
  else if("ADMIN".equals(role)){m.put("students",scalar("SELECT COUNT(*) FROM gc_users WHERE role='STUDENT'"));m.put("staff",scalar("SELECT COUNT(*) FROM gc_users WHERE role='STAFF'"));m.put("total",scalar("SELECT COUNT(*) FROM gc_grievances WHERE deleted_at IS NULL"));m.put("pending",scalar("SELECT COUNT(*) FROM gc_grievances WHERE status='PENDING' AND deleted_at IS NULL"));m.put("unassigned",scalar("SELECT COUNT(*) FROM gc_grievances g WHERE g.status='PENDING' AND g.deleted_at IS NULL AND NOT EXISTS (SELECT 1 FROM gc_assignments a WHERE a.grievance_id=g.grievance_id)"));m.put("resolved",scalar("SELECT COUNT(*) FROM gc_grievances WHERE status='RESOLVED' AND deleted_at IS NULL"));m.put("completed",scalar("SELECT COUNT(*) FROM gc_assignments a JOIN gc_grievances g ON g.grievance_id=a.grievance_id WHERE a.status='COMPLETED' AND g.deleted_at IS NULL"));}
  else{String scope="deleted_at IS NULL AND department=?"+("TEACHER".equals(role)||"CLASS_TEACHER".equals(role)?" AND section=?":"");for(String s:new String[]{"total","pending","resolved"})m.put(s,count("SELECT COUNT(*) FROM gc_grievances WHERE "+scope+("total".equals(s)?"":" AND status='"+s.toUpperCase()+"'"),u.getDepartment(),("TEACHER".equals(role)||"CLASS_TEACHER".equals(role))?u.getSection():null));}return m;}
 private long count(String sql,long id)throws SQLException{return count(sql,id,null);}
 private long count(String sql,long id,Object status)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(sql)){p.setLong(1,id);if(status!=null)p.setObject(2,status);try(ResultSet r=p.executeQuery()){r.next();return r.getLong(1);}}}
 private long count(String sql,Object department,Object section)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(sql)){p.setObject(1,department);if(section!=null)p.setObject(2,section);try(ResultSet r=p.executeQuery()){r.next();return r.getLong(1);}}}
 private long scalar(String sql)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(sql);ResultSet r=p.executeQuery()){r.next();return r.getLong(1);}}
}
